import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Fill contact form, then abruptly navigate away and return to same form', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Which service are you interested in', 'Functional Testing')
  await opFill(page, 'Name', 'Test User')
  await opFill(page, 'Email', 'test@example.com')
  await opFill(page, 'Message', 'Just checking your site functionality.')
  await opClick(page, 'link', 'Home')
  await opClick(page, 'link', 'Contact')
  await opClick(page, 'button', 'Submit')
})
